export const SPEED_TEST_TEXTS_EN = [
  "Typing with precision is the first step toward genuine speed. When your fingers instinctively know where each key resides, words flow onto the screen without conscious effort. Focus on rhythm and clarity rather than rushing through the sentences.",
  "Touch typing frees your mind to focus entirely on ideas. Instead of constantly glancing down at the keys, your eyes remain fixed on the monitor. The tactile bumps on the F and J keys always guide your index fingers back home.",
  "Speed naturally follows accuracy. Rushing through exercises only reinforces bad habits and increases error rates. Practice at a relaxed, steady tempo until your movements become clean, fluid, and effortless.",
  "Mastering the keyboard transforms how you write and communicate. Consistent daily practice of just fifteen minutes creates strong muscle memory that will serve you throughout your entire career.",
  "Every keystroke should feel deliberate and controlled. Keep your wrists hovering lightly above the desk, maintain good posture, and let each finger cover its designated column without unnecessary strain.",
];

export function getRandomTestText(layout: Layout): string {
  const texts = layout === "ru" ? SPEED_TEST_TEXTS_RU : SPEED_TEST_TEXTS_EN;
  return texts[Math.floor(Math.random() * texts.length)];
}

